import { sql } from "drizzle-orm";
import {
  check,
  customType,
  index,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  smallint,
  text,
  timestamp,
  uuid,
} from "drizzle-orm/pg-core";
import type { KdfParams } from "../../shared/schemas/keys.ts";
import { RECORD_KINDS } from "../../shared/schemas/vault.ts";
import { session, user } from "./auth-schema.ts";

// Better Auth's tables, generated by its CLI (see worker/db/README.md).
export * from "./auth-schema.ts";

/** Binary values: IVs, salts, wrapped keys, ciphertexts, token hashes. */
const bytes = customType<{ data: Uint8Array; driverData: Uint8Array }>({
  dataType: () => "bytea",
});

const createdAt = () =>
  timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
const updatedAt = () =>
  timestamp("updated_at", { withTimezone: true }).notNull().defaultNow();
const ownedBy = () =>
  text("user_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" });
const byteLength = (column: unknown, bytes: number) =>
  sql`octet_length(${column}) = ${sql.raw(String(bytes))}`;

/**
 * Who may sign in: the closed beta's invite list. Emails are personal data, so
 * the list lives here, never in code. Managed with `npm run users`.
 */
export const allowedEmails = pgTable(
  "allowed_emails",
  {
    email: text("email").primaryKey(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  // Stored lowercase, so lookups need no normalization at query time.
  (table) => [
    check("email_lowercase", sql`${table.email} = lower(${table.email})`),
  ],
);

/**
 * Emails that may never sign in, even if invited again by mistake: a second
 * line of defense behind the invite list. `npm run users -- block` adds the
 * email here, removes its invite and ends its sessions in one statement.
 */
export const blockedEmails = pgTable(
  "blocked_emails",
  {
    email: text("email").primaryKey(),
    // Why, in the owner's words; never shown to the blocked person.
    reason: text("reason"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => [
    check(
      "blocked_email_lowercase",
      sql`${table.email} = lower(${table.email})`,
    ),
  ],
);

/*
 * End-to-end encryption (phase 3). The server stores only what src/crypto
 * produces: wrapped copies of each user's data key and encrypted records. None
 * of it can be read without a key the server never sees. Every table belongs to
 * a user and disappears with the account (on delete cascade), which is what
 * makes account deletion and `npm run users -- delete` complete.
 */

/** Wrapped copies of the data key: one per passphrase and recovery key. */
export const userKeySlots = pgTable(
  "user_key_slots",
  {
    userId: ownedBy(),
    kind: text("kind", { enum: ["passphrase", "recovery"] }).notNull(),
    // Argon2id settings, stored with the slot so they can change later.
    kdf: jsonb("kdf").$type<KdfParams>(),
    salt: bytes("salt").notNull(),
    iv: bytes("iv").notNull(),
    wrappedKey: bytes("wrapped_key").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.kind] }),
    check("key_slot_kind", sql`${table.kind} in ('passphrase', 'recovery')`),
    check(
      "key_slot_kdf_on_passphrase_only",
      sql`(${table.kind} = 'passphrase') = (${table.kdf} is not null)`,
    ),
    check("key_slot_salt_length", byteLength(table.salt, 16)),
    check("key_slot_iv_length", byteLength(table.iv, 12)),
    check("key_slot_wrapped_key_length", byteLength(table.wrappedKey, 48)),
  ],
);

/**
 * Encrypted records. The server sees the kind, the size bucket, the revision
 * and the dates; never the content. The id is made by the browser (it is part
 * of the AAD), so the key is (user, id): ids of different users never clash.
 */
export const vaultRecords = pgTable(
  "vault_records",
  {
    userId: ownedBy(),
    id: uuid("id").notNull(),
    kind: text("kind", { enum: RECORD_KINDS }).notNull(),
    revision: integer("revision").notNull(),
    envelopeVersion: smallint("envelope_version").notNull(),
    iv: bytes("iv").notNull(),
    ciphertext: bytes("ciphertext").notNull(),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (table) => [
    primaryKey({ columns: [table.userId, table.id] }),
    index("vault_records_user_kind").on(table.userId, table.kind),
    check(
      "vault_record_kind",
      sql`${table.kind} in (${sql.raw(RECORD_KINDS.map((kind) => `'${kind}'`).join(", "))})`,
    ),
    check("vault_record_revision", sql`${table.revision} >= 1`),
    check("vault_record_iv_length", byteLength(table.iv, 12)),
  ],
);

/**
 * The server half of "Remember this device": the data key wrapped by a key
 * that exists only on that device. It belongs to one sign-in session, so
 * signing out, revoking the session or its expiry deletes it; the browser must
 * also present the session-only cookie whose hash is stored here.
 */
export const deviceUnlocks = pgTable(
  "device_unlocks",
  {
    sessionId: text("session_id")
      .primaryKey()
      .references(() => session.id, { onDelete: "cascade" }),
    userId: ownedBy(),
    tokenHash: bytes("token_hash").notNull(),
    iv: bytes("iv").notNull(),
    wrappedKey: bytes("wrapped_key").notNull(),
    createdAt: createdAt(),
  },
  (table) => [
    check("device_unlock_token_hash_length", byteLength(table.tokenHash, 32)),
    check("device_unlock_iv_length", byteLength(table.iv, 12)),
    check("device_unlock_wrapped_key_length", byteLength(table.wrappedKey, 48)),
  ],
);

/**
 * Request counters for the app's own routes (Better Auth keeps its own in
 * `rate_limit`). One row per user and bucket, reset when its window ends.
 */
export const apiRateLimits = pgTable(
  "api_rate_limits",
  {
    userId: ownedBy(),
    bucket: text("bucket").notNull(),
    windowStart: timestamp("window_start", { withTimezone: true }).notNull(),
    count: integer("count").notNull(),
  },
  (table) => [primaryKey({ columns: [table.userId, table.bucket] })],
);
